export class EnemyManager {
  constructor(scene, world, fx, audio, camera) {
    this.scene = scene;
    this.world = world;
    this.fx = fx;
    this.audio = audio;
    this.camera = camera;
    this.enemies = [];
    this.hitMeshes = [];
    this.onKilled = null;
    this.onPlayerDamage = null;
    this.onEnemyShoot = null;
    this.difficulty = 1;
    this._v = new THREE.Vector3();
    this._v2 = new THREE.Vector3();
    this._eye = new THREE.Vector3();
    this._playerEye = new THREE.Vector3();
    this._muzzle = new THREE.Vector3();
    this._tmp = new THREE.Vector3();
  }

  clear() {
    for (const e of this.enemies) {
      this.scene.remove(e.group);
      e.group.traverse((o) => {
        if (o.geometry) o.geometry.dispose();
      });
      if (e.bar?.tex) e.bar.tex.dispose();
    }
    this.enemies.length = 0;
    this.hitMeshes.length = 0;
  }

  reset(difficulty = 1) {
    this.clear();
    this.difficulty = difficulty;
  }

  get aliveCount() {
    let n = 0;
    for (const e of this.enemies) if (!e.dead) n++;
    return n;
  }

  getHitMeshes() {
    this.hitMeshes.length = 0;
    for (const e of this.enemies) {
      if (e.dead) continue;
      for (const m of e.hitMeshes) this.hitMeshes.push(m);
    }
    return this.hitMeshes;
  }

  spawn(typeName, point, options = {}) {
    const type = TYPES[typeName] || TYPES.grunt;
    const group = new THREE.Group();
    const scale = type.scale;
    const mats = [];
    const mat = (opts) => {
      const m = new THREE.MeshStandardMaterial(opts);
      mats.push(m);
      return m;
    };
    const uniform = mat({ color: type.uniform, roughness: 0.9, metalness: 0.03 });
    const vest = mat({ color: type.vest, roughness: 0.72, metalness: 0.18 });
    const helmet = mat({ color: type.helmet, roughness: 0.62, metalness: 0.24 });
    const skin = mat({ color: 0x8b6a51, roughness: 0.94, metalness: 0 });
    const dark = mat({ color: 0x151817, roughness: 0.55, metalness: 0.35 });
    const accent = new THREE.MeshBasicMaterial({ color: type.visor });
    const glass = new THREE.MeshStandardMaterial({
      color: 0x1b2525,
      roughness: 0.15,
      metalness: 0.7,
      emissive: 0x33120d,
      emissiveIntensity: 1.2,
    });

    const hitMeshes = [];
    const addHit = (mesh, part) => {
      mesh.userData.enemy = null;
      mesh.userData.part = part;
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      group.add(mesh);
      hitMeshes.push(mesh);
      return mesh;
    };

    // hips / torso
    const hips = new THREE.Mesh(rounded(0.46, 0.25, 0.3, 0.04), uniform);
    hips.position.y = 0.95;
    addHit(hips, "body");
    const torso = new THREE.Mesh(rounded(0.52, 0.62, 0.33, 0.06), uniform);
    torso.position.y = 1.35;
    addHit(torso, "body");
    const plate = new THREE.Mesh(rounded(0.48, 0.46, 0.2, 0.045), vest);
    plate.position.set(0, 1.37, -0.13);
    addHit(plate, "body");
    // chest pouches
    for (let i = 0; i < 3; i++) {
      const pouch = new THREE.Mesh(rounded(0.12, 0.12, 0.07, 0.01), dark);
      pouch.position.set(-0.15 + i * 0.15, 1.2, -0.25);
      group.add(pouch);
    }
    // shoulder pads
    for (const side of [-1, 1]) {
      const pad = new THREE.Mesh(rounded(0.18, 0.14, 0.26, 0.03), vest);
      pad.position.set(side * 0.32, 1.58, 0);
      addHit(pad, "body");
    }
    // neck + head
    const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.1, 0.12, 8), skin);
    neck.position.y = 1.7;
    group.add(neck);
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.175, 12, 10), skin);
    head.position.set(0, 1.83, 0);
    head.scale.set(0.92, 1.04, 0.94);
    addHit(head, "head");
    const helmetMesh = new THREE.Mesh(
      new THREE.SphereGeometry(0.2, 14, 8, 0, Math.PI * 2, 0, Math.PI * 0.58),
      helmet,
    );
    helmetMesh.position.set(0, 1.86, 0);
    helmetMesh.scale.set(1.02, 0.9, 1.05);
    addHit(helmetMesh, "head");
    const visor = new THREE.Mesh(new THREE.BoxGeometry(0.26, 0.055, 0.04), accent);
    visor.position.set(0, 1.85, -0.17);
    group.add(visor);
    // helmet lamp
    const lamp = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.06, 0.05), new THREE.MeshBasicMaterial({ color: 0xffe0a0 }));
    lamp.position.set(0.1, 1.94, -0.16);
    group.add(lamp);
    // backpack
    const pack = new THREE.Mesh(rounded(0.36, 0.46, 0.2, 0.03), dark);
    pack.position.set(0, 1.38, 0.24);
    addHit(pack, "body");
    const antenna = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.5, 4), dark);
    antenna.position.set(0.14, 1.8, 0.3);
    group.add(antenna);
    // arms (pivot groups)
    const makeArm = (side) => {
      const pivot = new THREE.Group();
      pivot.position.set(side * 0.33, 1.55, 0);
      const upper = new THREE.Mesh(rounded(0.15, 0.38, 0.16, 0.03), uniform);
      upper.position.y = -0.17;
      upper.castShadow = true;
      pivot.add(upper);
      const fore = new THREE.Mesh(rounded(0.13, 0.32, 0.14, 0.025), uniform);
      fore.position.set(0, -0.5, -0.04);
      fore.rotation.x = 0.18;
      fore.castShadow = true;
      pivot.add(fore);
      const hand = new THREE.Mesh(rounded(0.12, 0.12, 0.16, 0.025), dark);
      hand.position.set(0, -0.68, -0.08);
      pivot.add(hand);
      return pivot;
    };
    const leftArm = makeArm(-1);
    const rightArm = makeArm(1);
    group.add(leftArm, rightArm);
    // legs
    const makeLeg = (side) => {
      const pivot = new THREE.Group();
      pivot.position.set(side * 0.13, 0.9, 0);
      const thigh = new THREE.Mesh(rounded(0.19, 0.4, 0.22, 0.035), uniform);
      thigh.position.y = -0.2;
      thigh.castShadow = true;
      pivot.add(thigh);
      const shin = new THREE.Mesh(rounded(0.16, 0.38, 0.18, 0.03), uniform);
      shin.position.set(0, -0.58, 0.015);
      shin.castShadow = true;
      pivot.add(shin);
      const boot = new THREE.Mesh(rounded(0.19, 0.13, 0.3, 0.03), dark);
      boot.position.set(0, -0.81, -0.05);
      pivot.add(boot);
      return pivot;
    };
    const leftLeg = makeLeg(-1);
    const rightLeg = makeLeg(1);
    group.add(leftLeg, rightLeg);
    // knee pads
    for (const side of [-1, 1]) {
      const knee = new THREE.Mesh(rounded(0.17, 0.16, 0.13, 0.02), vest);
      knee.position.set(side * 0.13, 0.52, -0.09);
      group.add(knee);
    }
    // rifle in hands
    const gun = new THREE.Group();
    gun.position.set(0.24, 1.3, -0.34);
    const gunBody = new THREE.Mesh(rounded(0.09, 0.11, 0.62, 0.015), dark);
    gunBody.castShadow = true;
    gun.add(gunBody);
    const gunBarrel = new THREE.Mesh(new THREE.CylinderGeometry(0.014, 0.016, 0.35, 6), dark);
    gunBarrel.position.set(0, 0.02, -0.44);
    gunBarrel.rotation.x = Math.PI / 2;
    gun.add(gunBarrel);
    const gunMag = new THREE.Mesh(rounded(0.06, 0.17, 0.09, 0.01), vest);
    gunMag.position.set(0, -0.12, -0.02);
    gunMag.rotation.x = 0.14;
    gun.add(gunMag);
    const gunStock = new THREE.Mesh(rounded(0.08, 0.12, 0.2, 0.02), uniform);
    gunStock.position.set(0, -0.01, 0.38);
    gun.add(gunStock);
    const muzzle = new THREE.Object3D();
    muzzle.position.set(0, 0.02, -0.67);
    gun.add(muzzle);
    group.add(gun);

    // health bar
    const bar = makeHealthTexture();
    drawHealth(bar, 1);
    const barMat = new THREE.SpriteMaterial({ map: bar.tex, transparent: true, depthTest: false, depthWrite: false });
    const barSprite = new THREE.Sprite(barMat);
    barSprite.scale.set(0.92, 0.17, 1);
    barSprite.position.set(0, 2.2, 0);
    barSprite.visible = false;
    group.add(barSprite);

    // radio glow
    const radio = new THREE.Mesh(new THREE.SphereGeometry(0.025, 6, 6), new THREE.MeshBasicMaterial({ color: type.visor }));
    radio.position.set(0.28, 1.44, 0.19);
    group.add(radio);

    group.position.copy(point);
    group.position.y = 0;
    group.scale.setScalar(scale);
    group.rotation.y = Math.random() * Math.PI * 2;
    this.scene.add(group);

    const health = Math.round(type.health * (1 + (this.difficulty - 1) * 0.14));
    const enemy = {
      id: nextId++,
      type: typeName,
      def: type,
      group,
      root: group,
      position: group.position,
      health,
      maxHealth: health,
      speed: type.speed * (1 + (this.difficulty - 1) * 0.035),
      damage: type.damage * (1 + (this.difficulty - 1) * 0.1),
      hitMeshes,
      bar,
      barSprite,
      mats,
      accent,
      head,
      torso,
      leftArm,
      rightArm,
      leftLeg,
      rightLeg,
      muzzle,
      gun,
      dead: false,
      deathTimer: 0,
      state: "spawn",
      attackTimer: 1 + Math.random() * 1.2,
      burstLeft: 0,
      burstTimer: 0,
      walkPhase: Math.random() * 6,
      flash: 0,
      losTimer: Math.random() * 0.12,
      hasLos: false,
      distance: 999,
      lastHitBy: null,
      spawnTimer: 0.7,
      barTimer: 0,
      scale,
      meleeTimer: 0,
    };
    for (const m of hitMeshes) m.userData.enemy = enemy;
    this.enemies.push(enemy);
    this.fx.dust(new THREE.Vector3(point.x, 0.1, point.z), 10, 1.4);
    return enemy;
  }

  damage(enemy, amount, part, point, dir) {
    if (!enemy || enemy.dead) return { killed: false, enemy, headshot: false };
    const headshot = part === "head";
    enemy.health -= amount;
    enemy.flash = 1;
    enemy.barSprite.visible = true;
    enemy.barTimer = 3;
    drawHealth(enemy.bar, Math.max(0, enemy.health / enemy.maxHealth));
    this.fx.blood(point, dir.clone().multiplyScalar(-1));
    if (enemy.health <= 0) {
      this.kill(enemy, headshot);
      return { killed: true, enemy, headshot, score: enemy.def.score * (headshot ? 1.5 : 1) };
    }
    return { killed: false, enemy, headshot, score: 0 };
  }

  kill(enemy, headshot) {
    if (enemy.dead) return;
    enemy.dead = true;
    enemy.deathTimer = 0;
    enemy.state = "dead";
    enemy.barSprite.visible = false;
    enemy.health = 0;
    const p = enemy.position;
    this.fx.blood(new THREE.Vector3(p.x, 1.3 * enemy.scale, p.z), new THREE.Vector3(0, 1, 0));
    this.fx.dust(new THREE.Vector3(p.x, 0.1, p.z), 7, 1);
    this.audio.kill();
    if (headshot) this.audio.headshot();
    this.onKilled?.(enemy, headshot);
  }

  update(dt, player, time) {
    const playerEye = this._playerEye.set(player.position.x, player.position.y + player.eyeHeight, player.position.z);
    for (let i = this.enemies.length - 1; i >= 0; i--) {
      const e = this.enemies[i];
      if (e.spawnTimer > 0) {
        e.spawnTimer -= dt;
      }
      if (e.dead) {
        e.deathTimer += dt;
        const t = Math.min(1, e.deathTimer / 0.6);
        e.group.rotation.x = -t * 1.48;
        e.group.position.y = -Math.max(0, e.deathTimer - 3.2) * 0.6;
        if (e.deathTimer > 6) {
          this.scene.remove(e.group);
          this.enemies.splice(i, 1);
        }
        continue;
      }

      if (e.flash > 0) {
        e.flash = Math.max(0, e.flash - dt * 9);
        for (const m of e.mats) {
          m.emissive.setRGB(e.flash * 0.85, e.flash * 0.08, 0);
          m.emissiveIntensity = e.flash * 2.2;
        }
      }
      if (e.barTimer > 0) {
        e.barTimer -= dt;
        if (e.barTimer <= 0) e.barSprite.visible = false;
      }

      const dx = player.position.x - e.position.x;
      const dz = player.position.z - e.position.z;
      const dist = Math.hypot(dx, dz);
      e.distance = dist;
      e.losTimer -= dt;
      if (e.losTimer <= 0) {
        e.losTimer = 0.12 + Math.random() * 0.08;
        this._eye.set(e.position.x, 1.58 * e.scale, e.position.z);
        e.hasLos = this.world.hasLineOfSight(this._eye, playerEye);
      }
      const canSee = e.hasLos && dist < e.def.range;
      const desiredYaw = Math.atan2(dx, dz) + Math.PI;
      e.group.rotation.y = dampAngle(e.group.rotation.y, desiredYaw, canSee ? 9 : 3, dt);
      e.group.position.y = 0;

      if (e.spawnTimer > 0) {
        e.group.position.y = -0.9 + (1 - e.spawnTimer / 0.7) * 0.9;
        continue;
      }

      // melee / close range
      if (dist < 2.0 && e.type === "rusher") {
        if (e.meleeTimer <= 0) {
          e.meleeTimer = 0.75;
          this.audio.shoot("enemy");
          this.fx.muzzle(e.muzzle.getWorldPosition(this._muzzle), this._v.set(dx, 0.2, dz).normalize());
          this.onPlayerDamage?.(e.damage * 1.4, e.position, "melee");
          this.onEnemyShoot?.(e);
        }
      }

      let moving = false;
      const attackRange = e.type === "rusher" ? 6.5 : e.def.range * 0.92;
      if (canSee && dist < attackRange) {
        moving = false;
        if (dist < 2.1 && e.type !== "rusher") {
          // back off slightly if player is on top of them
          const push = this.world.moveCircle(e.position.x, e.position.z, -dx / dist * dt * 1.1, -dz / dist * dt * 1.1, 0.38);
          e.position.x = push.x;
          e.position.z = push.z;
        }
        e.attackTimer -= dt;
        if (e.burstLeft > 0) {
          e.burstTimer -= dt;
          if (e.burstTimer <= 0) {
            this.fireAtPlayer(e, player, dist);
            e.burstLeft--;
            e.burstTimer = e.def.fireInterval * (0.85 + Math.random() * 0.3);
            if (e.burstLeft <= 0) e.attackTimer = e.def.cooldown * (0.75 + Math.random() * 0.5);
          }
        } else if (e.attackTimer <= 0) {
          e.burstLeft = e.def.burst;
          e.burstTimer = 0;
          e.attackTimer = e.def.cooldown;
        }
      } else {
        moving = true;
        let mx = dx / Math.max(dist, 0.001);
        let mz = dz / Math.max(dist, 0.001);
        // separation
        for (const other of this.enemies) {
          if (other === e || other.dead) continue;
          const sx = e.position.x - other.position.x;
          const sz = e.position.z - other.position.z;
          const sdist = Math.hypot(sx, sz);
          if (sdist > 0.001 && sdist < 1.2) {
            mx += (sx / sdist) * (1.2 - sdist) * 0.7;
            mz += (sz / sdist) * (1.2 - sdist) * 0.7;
          }
        }
        const len = Math.hypot(mx, mz) || 1;
        mx /= len;
        mz /= len;
        // simple obstacle whisker steering
        const candidates = [
          [mx, mz], [mx * 0.7 - mz * 0.7, mz * 0.7 + mx * 0.7],
          [mx * 0.7 + mz * 0.7, mz * 0.7 - mx * 0.7], [-mz, mx], [mz, -mx],
        ];
        let best = null;
        for (const [cx, cz] of candidates) {
          const nx = e.position.x + cx * 1.1;
          const nz = e.position.z + cz * 1.1;
          if (!this.world.collidesAt(nx, nz, 0.38)) { best = [cx, cz]; break; }
        }
        if (best) { mx = best[0]; mz = best[1]; }
        const step = e.speed * dt;
        const moved = this.world.moveCircle(e.position.x, e.position.z, mx * step, mz * step, 0.38);
        e.position.x = moved.x;
        e.position.z = moved.z;
        e.walkPhase += dt * e.speed * 3.5;
      }

      if (e.meleeTimer > 0) e.meleeTimer -= dt;
      const swing = moving ? Math.sin(e.walkPhase) : 0;
      e.leftLeg.rotation.x = swing * 0.55;
      e.rightLeg.rotation.x = -swing * 0.55;
      e.leftArm.rotation.x = -swing * 0.35 - 0.35;
      e.rightArm.rotation.x = -0.72 + Math.sin(time * 1.7 + e.id) * 0.02;
      e.leftArm.rotation.z = 0.12;
      e.rightArm.rotation.z = -0.2;
      e.group.position.y = moving ? Math.abs(Math.sin(e.walkPhase)) * 0.025 : 0;

      if (e.barSprite.visible) {
        e.barSprite.position.y = 2.18 + (moving ? Math.abs(Math.sin(e.walkPhase)) * 0.025 : 0);
      }
    }
  }

  fireAtPlayer(e, player, dist) {
    const muzzlePos = e.muzzle.getWorldPosition(new THREE.Vector3());
    const eye = player.position.clone();
    eye.y += player.eyeHeight - 0.12;
    // accuracy falls with distance and player movement
    let chance = 0.68 - dist * 0.0125 + (player.crouching ? -0.11 : 0) + (player.isMoving ? -0.09 : 0);
    if (e.type === "heavy") chance -= 0.08;
    chance = THREE.MathUtils.clamp(chance, 0.12, 0.58);
    const hit = Math.random() < chance;
    const target = eye.clone();
    if (!hit) {
      target.x += (Math.random() - 0.5) * 2.2;
      target.y += (Math.random() - 0.5) * 1.5;
      target.z += (Math.random() - 0.5) * 2.2;
    }
    this.fx.tracer(muzzlePos, target, e.type === "heavy" ? 0xff8a4a : 0xffb36b);
    this.fx.muzzle(muzzlePos, target.clone().sub(muzzlePos).normalize());
    this.audio.shoot(e.type === "heavy" ? "heavy" : "enemy");
    if (hit) {
      this.onPlayerDamage?.(e.damage, e.position, e.type);
    }
    this.onEnemyShoot?.(e);
  }

  applyExplosion(point, radius, damage) {
    for (const e of this.enemies) {
      if (e.dead) continue;
      const d = e.position.distanceTo(point);
      if (d < radius) {
        const falloff = 1 - d / radius;
        const hitPoint = new THREE.Vector3(e.position.x, 1.2, e.position.z);
        this.damage(e, damage * falloff, "body", hitPoint, point.clone().sub(hitPoint).normalize());
        e.group.position.addScaledVector(e.position.clone().sub(point).setY(0).normalize(), 0.3 * falloff);
      }
    }
  }
}

function dampAngle(current, target, lambda, dt) {
  let delta = ((target - current + Math.PI) % (Math.PI * 2)) - Math.PI;
  if (delta < -Math.PI) delta += Math.PI * 2;
  return current + delta * (1 - Math.exp(-lambda * dt));
}

export { TYPES };

import * as THREE from "three";

export class Player {
  constructor(camera, world, audio) {
    this.camera = camera;
    this.world = world;
    this.audio = audio;
    this.position = new THREE.Vector3(0, 0, 15);
    this.velocity = new THREE.Vector3();
    this.yaw = 0.02;
    this.pitch = -0.02;
    this.recoilPitch = 0;
    this.recoilYaw = 0;
    this.recoilVelPitch = 0;
    this.recoilVelYaw = 0;
    this.sensitivity = 1;
    this.invertY = false;
    this.eyeHeight = 1.68;
    this.standHeight = 1.68;
    this.crouchHeight = 1.05;
    this.radius = 0.42;
    this.health = 100;
    this.maxHealth = 100;
    this.armor = 60;
    this.maxArmor = 100;
    this.crouching = false;
    this.grounded = true;
    this.isMoving = false;
    this.isSprinting = false;
    this.bobPhase = 0;
    this.stepTimer = 0;
    this.landTimer = 0;
    this.lastDamageTime = -99;
    this.time = 0;
    this.shake = 0;
    this.shakeEnabled = true;
    this.damageFlash = 0;
    this.invuln = 0;
    this.fovBase = 78;
    this.fovCurrent = 78;
    this.ads = 0;
    this.adsFov = 58;
    this.stride = 0;
    this.tilt = 0;
    this.onDamage = null;
    this.onStep = null;
    this.onDeath = null;
    this.dead = false;
    this._forward = new THREE.Vector3();
    this._right = new THREE.Vector3();
    this._tmp = new THREE.Vector3();
    this._lastDamageFrom = new THREE.Vector3();
  }

  reset() {
    this.position.set(0, 0, 15);
    this.velocity.set(0, 0, 0);
    this.yaw = 0.02;
    this.pitch = -0.02;
    this.recoilPitch = 0;
    this.recoilYaw = 0;
    this.recoilVelPitch = 0;
    this.recoilVelYaw = 0;
    this.health = 100;
    this.armor = 60;
    this.crouching = false;
    this.grounded = true;
    this.dead = false;
    this.isMoving = false;
    this.isSprinting = false;
    this.bobPhase = 0;
    this.stepTimer = 0;
    this.shake = 0;
    this.damageFlash = 0;
    this.invuln = 0;
    this.lastDamageTime = -99;
    this.time = 0;
    this.fovCurrent = this.fovBase;
    this.ads = 0;
    this.camera.fov = this.fovBase;
    this.camera.updateProjectionMatrix();
    this.applyCamera(0);
  }

  look(dx, dy) {
    const mult = 0.00215 * this.sensitivity;
    this.yaw -= dx * mult;
    this.pitch -= dy * mult * (this.invertY ? -1 : 1);
    this.pitch = THREE.MathUtils.clamp(this.pitch, -1.42, 1.42);
  }

  addRecoil(pitch, yaw) {
    this.recoilVelPitch += pitch * 12;
    this.recoilVelYaw += yaw * 12;
  }

  damage(amount, fromPosition, source = "bullet") {
    if (this.dead || this.invuln > 0) return false;
    this.invuln = 0.06;
    let remaining = amount;
    if (this.armor > 0) {
      const absorbed = Math.min(this.armor, amount * 0.52);
      this.armor = Math.max(0, this.armor - absorbed);
      remaining -= absorbed;
    }
    this.health = Math.max(0, this.health - remaining);
    this.lastDamageTime = this.time;
    this.damageFlash = Math.min(1, this.damageFlash + 0.55 + amount * 0.012);
    this.shake = Math.min(1.2, this.shake + 0.2 + amount * 0.01);
    if (fromPosition) this._lastDamageFrom.copy(fromPosition);
    this.audio.hurt();
    this.onDamage?.(amount, fromPosition, source, this.health);
    if (this.health <= 0) {
      this.dead = true;
      this.audio.defeat();
      this.onDeath?.();
      return true;
    }
    return false;
  }

  heal(amount) {
    this.health = Math.min(this.maxHealth, this.health + amount);
  }

  addArmor(amount) {
    this.armor = Math.min(this.maxArmor, this.armor + amount);
  }

  setAds(amount, fov) {
    this.ads = amount;
    this.adsFov = fov;
  }

  update(dt, input, weapon) {
    this.time += dt;
    this.invuln = Math.max(0, this.invuln - dt);
    this.damageFlash = Math.max(0, this.damageFlash - dt * 1.35);
    this.shake = Math.max(0, this.shake - dt * 3.2);
    this.landTimer = Math.max(0, this.landTimer - dt);

    // health regeneration after 4.4 seconds without damage
    if (!this.dead && this.time - this.lastDamageTime > 4.4 && this.health < this.maxHealth) {
      this.health = Math.min(this.maxHealth, this.health + dt * 18);
    }

    const crouchTarget = this.crouching ? this.crouchHeight : this.standHeight;
    this.eyeHeight = THREE.MathUtils.damp(this.eyeHeight, crouchTarget, 14, dt);

    const forwardInput = (input.forward ? 1 : 0) - (input.back ? 1 : 0);
    const rightInput = (input.right ? 1 : 0) - (input.left ? 1 : 0);
    const wantsMove = forwardInput !== 0 || rightInput !== 0;
    this.isSprinting = input.sprint && forwardInput > 0 && !this.crouching && this.ads < 0.25 && !this.dead;
    const speed = this.dead ? 0 : this.crouching ? 3.0 : this.ads > 0.5 ? 3.2 : this.isSprinting ? 9.2 : 5.6;

    this._forward.set(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
    this._right.set(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
    const desired = this._tmp.set(0, 0, 0)
      .addScaledVector(this._forward, forwardInput)
      .addScaledVector(this._right, rightInput);
    if (desired.lengthSq() > 1) desired.normalize();

    const accel = this.grounded ? 14 : 4;
    const targetVx = desired.x * speed;
    const targetVz = desired.z * speed;
    this.velocity.x = THREE.MathUtils.damp(this.velocity.x, targetVx, accel, dt);
    this.velocity.z = THREE.MathUtils.damp(this.velocity.z, targetVz, accel, dt);

    this.isMoving = wantsMove && !this.dead && Math.hypot(this.velocity.x, this.velocity.z) > 0.6;

    if (input.jump && this.grounded && !this.crouching && !this.dead) {
      this.velocity.y = 7.4;
      this.grounded = false;
      input.jump = false;
      this.audio.jump();
    }

    if (!this.grounded) {
      this.velocity.y -= 25 * dt;
    }
    this.position.x += this.velocity.x * dt;
    this.position.z += this.velocity.z * dt;
    const moved = this.world.moveCircle(this.position.x, this.position.z, 0, 0, this.radius);
    if (moved.x !== this.position.x || moved.z !== this.position.z) {
      // if we somehow ended inside geometry, pull back toward the valid point
      this.position.x = moved.x;
      this.position.z = moved.z;
    }
    this.position.y += this.velocity.y * dt;
    if (this.position.y <= 0) {
      if (!this.grounded && this.velocity.y < -4) {
        this.audio.land();
        this.landTimer = 0.25;
        this.shake = Math.min(1, this.shake + Math.min(0.35, -this.velocity.y * 0.03));
      }
      this.position.y = 0;
      this.velocity.y = 0;
      this.grounded = true;
    } else {
      this.grounded = false;
    }

    if (this.isMoving && this.grounded) {
      this.bobPhase += dt * (this.isSprinting ? 12.5 : this.crouching ? 5.2 : 8.3);
      const interval = this.isSprinting ? 0.3 : this.crouching ? 0.62 : 0.42;
      this.stepTimer -= dt;
      if (this.stepTimer <= 0) {
        this.stepTimer = interval;
        this.audio.footstep(this.position.x > 18 || this.position.z < -20 ? "concrete" : "sand");
        this.onStep?.(this.isSprinting);
      }
    } else {
      this.bobPhase += dt * 1.4;
    }

    // recoil spring
    this.recoilVelPitch += (-this.recoilPitch * 120 - this.recoilVelPitch * 14) * dt;
    this.recoilVelYaw += (-this.recoilYaw * 120 - this.recoilVelYaw * 14) * dt;
    this.recoilPitch += this.recoilVelPitch * dt;
    this.recoilYaw += this.recoilVelYaw * dt;
    this.recoilPitch = THREE.MathUtils.clamp(this.recoilPitch, -0.12, 0.18);
    this.recoilYaw = THREE.MathUtils.clamp(this.recoilYaw, -0.08, 0.08);

    const moveAmount = Math.min(1, Math.hypot(this.velocity.x, this.velocity.z) / 5.6);
    const fovTarget = THREE.MathUtils.lerp(this.fovBase + (this.isSprinting ? 5 : 0), this.adsFov, this.ads);
    this.fovCurrent = THREE.MathUtils.damp(this.fovCurrent, fovTarget, 9, dt);
    this.camera.fov = this.fovCurrent;
    this.camera.updateProjectionMatrix();

    this.applyCamera(dt, moveAmount);
  }

  applyCamera(dt, moveAmount = 0) {
    const bob = this.isMoving && this.grounded
      ? Math.sin(this.bobPhase) * 0.032 * (this.isSprinting ? 1.35 : 1) * (1 - this.ads * 0.7)
      : Math.sin(this.bobPhase) * 0.004;
    const bobSide = this.isMoving && this.grounded
      ? Math.cos(this.bobPhase * 0.5) * 0.018 * (this.isSprinting ? 1.2 : 1) * (1 - this.ads * 0.7)
      : 0;
    const crouchDrop = 0;
    const shakeX = this.shakeEnabled ? (Math.random() - 0.5) * this.shake * 0.045 : 0;
    const shakeY = this.shakeEnabled ? (Math.random() - 0.5) * this.shake * 0.045 : 0;
    const side = (this.velocity.x * Math.cos(this.yaw) - this.velocity.z * Math.sin(this.yaw)) / 9.2;
    this.tilt = THREE.MathUtils.damp(this.tilt, -side * 0.026 + (this.crouching ? 0.012 : 0), 6, dt || 0.016);
    this.camera.position.set(
      this.position.x + bobSide + shakeX,
      this.position.y + this.eyeHeight + bob + crouchDrop + shakeY,
      this.position.z,
    );
    this.camera.rotation.order = "YXZ";
    this.camera.rotation.y = this.yaw + this.recoilYaw;
    this.camera.rotation.x = this.pitch + this.recoilPitch + (this.landTimer > 0 ? -0.03 * (this.landTimer / 0.25) : 0);
    this.camera.rotation.z = this.tilt;
  }

  get eyePosition() {
    return this._tmp.set(this.position.x, this.position.y + this.eyeHeight, this.position.z);
  }

  get healthRatio() {
    return this.health / this.maxHealth;
  }

  get lastDamageDirection() {
    return this._lastDamageFrom;
  }
}

import * as THREE from "three";
import { EffectComposer } from "three/addons/postprocessing/EffectComposer.js";
import { RenderPass } from "three/addons/postprocessing/RenderPass.js";
import { UnrealBloomPass } from "three/addons/postprocessing/UnrealBloomPass.js";
import { OutputPass } from "three/addons/postprocessing/OutputPass.js";
import { ShaderPass } from "three/addons/postprocessing/ShaderPass.js";
import { GameAudio } from "./audio.js";
import { Effects } from "./fx.js";
import { createWorld } from "./world.js";
import { Player } from "./player.js";
import { EnemyManager, TYPES } from "./enemies.js";
import { WeaponSystem, RIFLE, PISTOL } from "./weapons.js";
import "./style.css";

const $ = (id) => document.getElementById(id);
const clamp = THREE.MathUtils.clamp;

const WAVE_TABLE = [
  { grunt: 6, rusher: 1, heavy: 0 },
  { grunt: 7, rusher: 2, heavy: 0 },
  { grunt: 8, rusher: 3, heavy: 1 },
  { grunt: 9, rusher: 4, heavy: 2 },
  { grunt: 12, rusher: 5, heavy: 3 },
];
const WAVE_BRIEFS = [
  "Command, first element is moving through the east ruins. Hold the courtyard.",
  "Multiple squads converging. Watch the flanks and keep your rifle fed.",
  "Heavy signature detected on the north ridge. Break their push.",
  "They are throwing everything at the relay. Do not give them the courtyard.",
  "Final assault. Hold until extraction. Make every round count.",
];
const MAX_GRENADES = 3;

const GradeShader = {
  uniforms: {
    tDiffuse: { value: null },
    uTime: { value: 0 },
    uVignette: { value: 1.0 },
    uAberration: { value: 0.0015 },
    uGrain: { value: 0.055 },
    uFlash: { value: 0.0 },
    uResolution: { value: new THREE.Vector2(1, 1) },
  },
  vertexShader: /* glsl */ `
    varying vec2 vUv;
    void main() {
      vUv = uv;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: /* glsl */ `
    precision highp float;
    varying vec2 vUv;
    uniform sampler2D tDiffuse;
    uniform float uTime;
    uniform float uVignette;
    uniform float uAberration;
    uniform float uGrain;
    uniform float uFlash;
    uniform vec2 uResolution;

    float rand(vec2 co) {
      return fract(sin(dot(co.xy, vec2(12.9898, 78.233))) * 43758.5453123);
    }

    void main() {
      vec2 uv = vUv;
      vec2 centered = uv - 0.5;
      float dist = length(centered);
      float ab = uAberration * (0.25 + dist * 1.9);
      vec2 dir = normalize(centered + 0.0001);
      vec3 col;
      col.r = texture2D(tDiffuse, uv + dir * ab).r;
      col.g = texture2D(tDiffuse, uv).g;
      col.b = texture2D(tDiffuse, uv - dir * ab).b;

      // subtle warm highlights / cool shadows
      float luma = dot(col, vec3(0.299, 0.587, 0.114));
      col = mix(col, col * vec3(1.035, 1.005, 0.955), smoothstep(0.0, 0.75, luma) * 0.55);
      col = mix(col, col * vec3(0.94, 0.985, 1.055), smoothstep(0.55, 0.0, luma) * 0.5);

      float vig = smoothstep(0.92, 0.18, dist * uVignette);
      col *= mix(0.72, 1.0, vig);
      float grain = (rand(gl_FragCoord.xy + fract(uTime) * 193.0) - 0.5) * uGrain;
      col += grain;
      col += vec3(uFlash);
      gl_FragColor = vec4(max(col, 0.0), 1.0);
    }
  `,
};

class Game {
  constructor() {
    this.canvas = $("game");
    this.renderer = new THREE.WebGLRenderer({
      canvas: this.canvas,
      antialias: true,
      powerPreference: "high-performance",
      stencil: false,
    });
    this.renderer.setClearColor(0x0a0c0d, 1);
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.04;
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;

    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(78, 1, 0.045, 500);
    this.camera.rotation.order = "YXZ";
    this.scene.add(this.camera);

    this.settings = this.loadSettings();
    this.quality = this.settings.quality;
    this.applyRendererQuality();

    this.world = createWorld(this.scene, this.renderer, { quality: this.quality });
    this.audio = new GameAudio();
    this.fx = new Effects(this.scene, this.camera);
    this.player = new Player(this.camera, this.world, this.audio);
    this.enemies = new EnemyManager(this.scene, this.world, this.fx, this.audio, this.camera);
    this.weapon = new WeaponSystem(this.camera, this.scene, this.fx, this.audio);

    this.state = "menu";
    this.time = 0;
    this.menuTime = 0;
    this.clock = new THREE.Clock();
    this.pointerLocked = false;
    this.isMobile = matchMedia("(pointer: coarse)").matches || "ontouchstart" in window;
    this.input = {
      forward: false, back: false, left: false, right: false,
      sprint: false, crouch: false, jump: false, firing: false, ads: false,
    };
    this.wave = {
      number: 0,
      total: 0,
      killed: 0,
      queue: [],
      spawnTimer: 0,
      active: false,
      intermission: 0,
      victoryPending: false,
    };
    this.grenades = 2;
    this.grenadeCooldown = 0;
    this.grenadeProjectiles = [];
    this.pickups = [];
    this.score = 0;
    this.combo = 1;
    this.comboTimer = 0;
    this.lastKillTime = -99;
    this.stats = { kills: 0, headshots: 0, bestStreak: 0, streak: 0, shots: 0, hits: 0 };
    this.runTime = 0;
    this.deathTimer = 0;
    this.resultShown = false;
    this.hudTimer = 0;
    this.radarTimer = 0;
    this.damageDirTimer = 0;
    this.toastTimer = 0;
    this.subtitleTimer = 0;
    this.frame = 0;
    this.attractEnemies = [];
    this.attractPlayer = {
      position: new THREE.Vector3(0, 0, -1),
      eyeHeight: 1.68,
      crouching: false,
      isMoving: false,
      dead: false,
    };

    this.setupPost();
    this.bindUI();
    this.bindInput();
    this.bindMobile();
    this.updateBestDisplay();
    this.setupAttract();
    this.resize();
    window.addEventListener("resize", () => this.resize());
    document.addEventListener("visibilitychange", () => {
      if (document.hidden && this.state === "playing") this.pause();
    });
    this.loop = this.loop.bind(this);
    requestAnimationFrame(this.loop);
  }

  loadSettings() {
    let saved = {};
    try { saved = JSON.parse(localStorage.getItem("blacksite.settings") || "{}"); } catch { /* noop */ }
    return {
      sensitivity: Number(saved.sensitivity) || 1,
      volume: saved.volume === undefined ? 0.7 : Number(saved.volume),
      quality: saved.quality || "medium",
      invertY: Boolean(saved.invertY),
      shake: saved.shake === undefined ? true : Boolean(saved.shake),
    };
  }

  saveSettings() {
    try { localStorage.setItem("blacksite.settings", JSON.stringify(this.settings)); } catch { /* noop */ }
  }

  applySettingsToUI() {
    $("sens-input").value = String(this.settings.sensitivity);
    $("volume-input").value = String(Math.round(this.settings.volume * 100));
    $("quality-input").value = this.settings.quality;
    $("invert-input").checked = this.settings.invertY;
    $("shake-input").checked = this.settings.shake;
    $("sens-value").textContent = this.settings.sensitivity.toFixed(2);
    $("volume-value").textContent = String(Math.round(this.settings.volume * 100));
    this.player.sensitivity = this.settings.sensitivity;
    this.player.invertY = this.settings.invertY;
    this.player.shakeEnabled = this.settings.shake;
    this.audio.setVolume(this.settings.volume);
  }

  applyRendererQuality() {
    const dpr = window.devicePixelRatio || 1;
    const cap = this.quality === "high" ? 2 : this.quality === "medium" ? 1.5 : 1;
    this.renderer.setPixelRatio(Math.min(dpr, cap));
  }

  setupPost() {
    const size = new THREE.Vector2();
    this.renderer.getDrawingBufferSize(size);
    const target = new THREE.WebGLRenderTarget(Math.max(1, size.x), Math.max(1, size.y), {
      type: THREE.HalfFloatType,
      samples: this.quality === "high" ? 4 : 0,
      depthBuffer: true,
    });
    this.composer = new EffectComposer(this.renderer, target);
    this.renderPass = new RenderPass(this.scene, this.camera);
    this.composer.addPass(this.renderPass);
    this.bloom = new UnrealBloomPass(new THREE.Vector2(size.x, size.y), 0.54, 0.62, 0.86);
    this.composer.addPass(this.bloom);
    this.composer.addPass(new OutputPass());
    this.grade = new ShaderPass(GradeShader);
    this.grade.material.uniforms.uResolution.value.set(size.x, size.y);
    this.composer.addPass(this.grade);
    this.composer.setSize(window.innerWidth, window.innerHeight);
  }

  resize() {
    const w = window.innerWidth;
    const h = window.innerHeight;
    this.camera.aspect = w / Math.max(1, h);
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(w, h, false);
    if (this.composer) {
      this.composer.setSize(w, h);
      const db = new THREE.Vector2();
      this.renderer.getDrawingBufferSize(db);
      this.grade.material.uniforms.uResolution.value.copy(db);
    }
    if (this.bloom) this.bloom.resolution.set(w, h);
  }

  setQuality(q) {
    this.settings.quality = q;
    this.quality = q;
    this.applyRendererQuality();
    this.resize();
    this.bloom.enabled = q !== "low";
    if (this.quality === "low") {
      this.composer.setPixelRatio?.(1);
    }
    this.saveSettings();
  }

  bindUI() {
    $("deploy-btn").addEventListener("click", () => this.startGame());
    $("controls-btn").addEventListener("click", () => this.showModal("controls-modal"));
    $("settings-btn").addEventListener("click", () => this.showModal("settings-modal"));
    $("pause-settings-btn").addEventListener("click", () => this.showModal("settings-modal"));
    document.querySelectorAll("[data-close]").forEach((el) => {
      el.addEventListener("click", () => {
        const modal = $(el.getAttribute("data-close"));
        if (modal) modal.classList.add("hidden");
        this.audio.uiClick();
      });
    });
    $("resume-btn").addEventListener("click", () => this.resume());
    $("restart-btn").addEventListener("click", () => this.startGame());
    $("quit-btn").addEventListener("click", () => this.quitToMenu());
    $("redeploy-btn").addEventListener("click", () => this.startGame());
    $("result-menu-btn").addEventListener("click", () => this.quitToMenu());

    $("sens-input").addEventListener("input", (e) => {
      this.settings.sensitivity = Number(e.target.value);
      $("sens-value").textContent = this.settings.sensitivity.toFixed(2);
      this.player.sensitivity = this.settings.sensitivity;
      this.saveSettings();
    });
    $("volume-input").addEventListener("input", (e) => {
      this.settings.volume = Number(e.target.value) / 100;
      $("volume-value").textContent = e.target.value;
      this.audio.setVolume(this.settings.volume);
      this.saveSettings();
    });
    $("quality-input").addEventListener("change", (e) => {
      this.setQuality(e.target.value);
      this.toast(`QUALITY // ${String(e.target.value).toUpperCase()}`, "SETTING APPLIED");
    });
    $("invert-input").addEventListener("change", (e) => {
      this.settings.invertY = e.target.checked;
      this.player.invertY = this.settings.invertY;
      this.saveSettings();
    });
    $("shake-input").addEventListener("change", (e) => {
      this.settings.shake = e.target.checked;
      this.player.shakeEnabled = this.settings.shake;
      this.saveSettings();
    });

    this.applySettingsToUI();
    this.buildCompass();
    this.buildAmmoPips();
  }

  showModal(id) {
    this.audio.uiClick();
    const m = $(id);
    if (!m) return;
    m.classList.remove("hidden");
    if (id === "settings-modal") this.applySettingsToUI();
  }

  setupAttract() {
    this.enemies.clear();
    this.enemies.reset(1);
    this.enemies.onPlayerDamage = null;
    this.enemies.onKilled = null;
    this.enemies.onEnemyShoot = null;
    this.attractEnemies = [];
    const points = [this.world.spawnPoints[0], this.world.spawnPoints[2], this.world.spawnPoints[4], this.world.spawnPoints[6]];
    for (let i = 0; i < points.length; i++) {
      const e = this.enemies.spawn(i % 3 === 0 ? "heavy" : i % 2 ? "rusher" : "grunt", points[i]);
      e.spawnTimer = 0;
      e.attackTimer = 1.5 + i;
      this.attractEnemies.push(e);
    }
    for (const model of this.weapon.models) model.group.visible = false;
  }

  bindInput() {
    const keyMap = {
      KeyW: "forward", ArrowUp: "forward",
      KeyS: "back", ArrowDown: "back",
      KeyA: "left", ArrowLeft: "left",
      KeyD: "right", ArrowRight: "right",
    };
    window.addEventListener("keydown", (e) => {
      if (e.code === "Escape") {
        if (this.state === "playing") this.pause();
        else if (this.state === "paused") this.resume();
        return;
      }
      if (e.code === "KeyM") {
        this.audio.setMuted(!this.audio.muted);
        this.toast(this.audio.muted ? "AUDIO MUTED" : "AUDIO ONLINE", "");
        return;
      }
      if (this.state !== "playing") return;
      if (keyMap[e.code]) {
        this.input[keyMap[e.code]] = true;
        e.preventDefault();
      }
      if (e.code === "ShiftLeft" || e.code === "ShiftRight") this.input.sprint = true;
      if (e.code === "Space") { this.input.jump = true; e.preventDefault(); }
      if (e.code === "KeyC") { this.player.crouching = !this.player.crouching; this.audio.uiClick(); }
      if (e.code === "KeyR") this.weapon.startReload();
      if (e.code === "Digit1") this.weapon.switchTo(RIFLE);
      if (e.code === "Digit2") this.weapon.switchTo(PISTOL);
      if (e.code === "KeyG") this.throwGrenade();
      if (e.code === "KeyQ") this.weapon.toggleWeapon();
    });
    window.addEventListener("keyup", (e) => {
      if (keyMap[e.code]) this.input[keyMap[e.code]] = false;
      if (e.code === "ShiftLeft" || e.code === "ShiftRight") this.input.sprint = false;
      if (e.code === "Space") this.input.jump = false;
    });

    document.addEventListener("mousemove", (e) => {
      if (this.state !== "playing" || !this.pointerLocked) return;
      this.player.look(e.movementX || 0, e.movementY || 0);
      this.weapon.addLookSway(e.movementX || 0, e.movementY || 0);
    });
    document.addEventListener("mousedown", (e) => {
      if (this.state !== "playing") return;
      if (!this.pointerLocked) {
        this.requestLock();
        return;
      }
      if (e.button === 0) this.input.firing = true;
      if (e.button === 2) this.input.ads = true;
    });
    document.addEventListener("mouseup", (e) => {
      if (e.button === 0) this.input.firing = false;
      if (e.button === 2) this.input.ads = false;
    });
    this.canvas.addEventListener("contextmenu", (e) => e.preventDefault());
    this.canvas.addEventListener("click", () => {
      if (this.state === "playing" && !this.pointerLocked && !this.isMobile) this.requestLock();
    });

    document.addEventListener("pointerlockchange", () => {
      this.pointerLocked = document.pointerLockElement === this.canvas;
      if (this.state === "playing" && !this.pointerLocked && !this.isMobile) this.pause();
    });

    this.weapon.onHit = (result, headshot) => {
      this.showHitmarker(Boolean(result?.killed), headshot);
      if (headshot) this.audio.headshot();
      else this.audio.impact();
    };
    this.player.onDamage = (_amount, from, _source, health) => {
      this.showDamageDirection(from);
      this.audio.hurt();
      if (health < 30) this.setSubtitle("Vitals critical. Find cover.", 2.6);
    };
    this.player.onDeath = () => this.onDeath();
    this.enemies.onKilled = (enemy, headshot) => this.onEnemyKilled(enemy, headshot);
    this.enemies.onPlayerDamage = (amount, from, source) => this.player.damage(amount, from, source);
  }

  requestLock() {
    if (!this.pointerLocked && this.canvas.requestPointerLock) {
      try { this.canvas.requestPointerLock(); } catch { /* noop */ }
    }
  }

  bindMobile() {
    if (!this.isMobile) return;
    $("mobile-controls").classList.remove("hidden");
    const stick = $("stick-base");
    const knob = $("stick-knob");
    const zone = $("stick-zone");
    let stickId = null;
    let origin = { x: 0, y: 0 };
    const resetStick = () => {
      this.input.forward = this.input.back = this.input.left = this.input.right = false;
      if (knob) knob.style.transform = "translate(0px, 0px)";
    };
    zone.addEventListener("pointerdown", (e) => {
      if (this.state !== "playing") return;
      stickId = e.pointerId;
      zone.setPointerCapture(e.pointerId);
      const r = stick.getBoundingClientRect();
      origin = { x: r.left + r.width / 2, y: r.top + r.height / 2 };
      e.preventDefault();
    });
    zone.addEventListener("pointermove", (e) => {
      if (stickId !== e.pointerId || this.state !== "playing") return;
      let dx = e.clientX - origin.x;
      let dy = e.clientY - origin.y;
      const max = 48;
      const len = Math.hypot(dx, dy);
      if (len > max) { dx = (dx / len) * max; dy = (dy / len) * max; }
      if (knob) knob.style.transform = `translate(${dx}px, ${dy}px)`;
      this.input.left = dx < -12;
      this.input.right = dx > 12;
      this.input.forward = dy < -12;
      this.input.back = dy > 12;
      this.input.sprint = len > 42 && dy < -30;
      e.preventDefault();
    });
    const release = (e) => {
      if (stickId === e.pointerId) {
        stickId = null;
        resetStick();
      }
    };
    zone.addEventListener("pointerup", release);
    zone.addEventListener("pointercancel", release);

    const look = $("look-zone");
    let lookId = null;
    let last = { x: 0, y: 0 };
    look.addEventListener("pointerdown", (e) => {
      if (this.state !== "playing") return;
      lookId = e.pointerId;
      look.setPointerCapture(e.pointerId);
      last = { x: e.clientX, y: e.clientY };
      e.preventDefault();
    });
    look.addEventListener("pointermove", (e) => {
      if (lookId !== e.pointerId || this.state !== "playing") return;
      const dx = (e.clientX - last.x) * 2.1;
      const dy = (e.clientY - last.y) * 2.1;
      last = { x: e.clientX, y: e.clientY };
      this.player.look(dx, dy);
      this.weapon.addLookSway(dx, dy);
      e.preventDefault();
    });
    const lookRelease = (e) => { if (lookId === e.pointerId) lookId = null; };
    look.addEventListener("pointerup", lookRelease);
    look.addEventListener("pointercancel", lookRelease);

    const hold = (id, down, up) => {
      const el = $(id);
      if (!el) return;
      el.addEventListener("pointerdown", (e) => { e.preventDefault(); down(); el.setPointerCapture?.(e.pointerId); });
      el.addEventListener("pointerup", (e) => { e.preventDefault(); up?.(); });
      el.addEventListener("pointercancel", () => up?.());
      el.addEventListener("pointerleave", () => up?.());
    };
    hold("mobile-fire", () => { this.input.firing = true; }, () => { this.input.firing = false; });
    hold("mobile-aim", () => { this.input.ads = true; }, () => { this.input.ads = false; });
    hold("mobile-jump", () => { this.input.jump = true; }, () => { this.input.jump = false; });
    $("mobile-reload").addEventListener("click", () => { if (this.state === "playing") this.weapon.startReload(); });
    $("mobile-swap").addEventListener("click", () => { if (this.state === "playing") this.weapon.toggleWeapon(); });
    $("mobile-grenade").addEventListener("click", () => { if (this.state === "playing") this.throwGrenade(); });
    $("mobile-pause").addEventListener("click", () => { if (this.state === "playing") this.pause(); });
  }

  startGame() {
    this.audio.init().then(() => this.audio.resume()).catch(() => {});
    this.audio.setVolume(this.settings.volume);
    this.audio.uiClick();
    this.state = "playing";
    this.runTime = 0;
    this.deathTimer = 0;
    this.resultShown = false;
    this.score = 0;
    this.combo = 1;
    this.comboTimer = 0;
    this.grenades = 2;
    this.stats = { kills: 0, headshots: 0, bestStreak: 0, streak: 0, shots: 0, hits: 0 };
    this.wave = { number: 0, total: 0, killed: 0, queue: [], spawnTimer: 0, active: false, intermission: 2.8, victoryPending: false };
    this.enemies.clear();
    this.enemies.reset(1);
    this.enemies.onKilled = (enemy, headshot) => this.onEnemyKilled(enemy, headshot);
    this.enemies.onPlayerDamage = (amount, from, source) => this.player.damage(amount, from, source);
    this.enemies.onEnemyShoot = null;
    this.clearPickups();
    this.clearGrenades();
    this.player.reset();
    this.weapon.reset();
    this.weapon.models.forEach((m) => { m.group.visible = false; });
    this.weapon.models[RIFLE].group.visible = true;
    this.input.firing = false;
    this.input.ads = false;
    this.input.jump = false;
    this.input.forward = this.input.back = this.input.left = this.input.right = false;
    this.input.sprint = false;
    this.player.crouching = false;
    this.audio.resume();
    this.audio.waveStart();
    document.body.classList.add("playing");
    $("menu").classList.add("hidden");
    $("pause").classList.add("hidden");
    $("gameover").classList.add("hidden");
    $("hud").classList.remove("hidden");
    if (this.isMobile) $("mobile-controls").classList.remove("hidden");
    else this.requestLock();
    this.updateHud(true);
    this.setObjective("HOLD THE COMPOUND", "FIRST CONTACT IMMINENT");
    this.setSubtitle("Command to all units: uplink is dark, hostiles inbound. Hold the relay.", 4.5);
    this.toast("OPERATION DUSTLINE", "SURVIVE FIVE ASSAULT WAVES");
    this.spawnPickup("ammo", this.world.pickupSpots[0]);
    this.spawnPickup("health", this.world.pickupSpots[1]);
    this.spawnPickup("armor", this.world.pickupSpots[2]);
  }

  pause() {
    if (this.state !== "playing") return;
    this.state = "paused";
    this.input.firing = false;
    this.input.ads = false;
    document.body.classList.remove("playing");
    $("pause").classList.remove("hidden");
    $("pause-wave").textContent = String(Math.max(1, this.wave.number)).padStart(2, "0");
    $("pause-score").textContent = String(Math.floor(this.score)).padStart(6, "0");
    $("pause-kills").textContent = String(this.stats.kills);
    $("pause-accuracy").textContent = `${this.weapon.accuracy}%`;
    if (document.pointerLockElement) document.exitPointerLock();
    this.audio.uiClick();
  }

  resume() {
    if (this.state !== "paused") return;
    this.state = "playing";
    document.body.classList.add("playing");
    $("pause").classList.add("hidden");
    this.audio.resume();
    this.audio.uiClick();
    if (!this.isMobile) this.requestLock();
  }

  quitToMenu() {
    this.state = "menu";
    document.body.classList.remove("playing");
    $("pause").classList.add("hidden");
    $("gameover").classList.add("hidden");
    $("hud").classList.add("hidden");
    $("menu").classList.remove("hidden");
    this.enemies.clear();
    this.clearPickups();
    this.clearGrenades();
    this.weapon.models.forEach((m) => { m.group.visible = false; });
    this.setupAttract();
    if (document.pointerLockElement) document.exitPointerLock();
    this.audio.uiClick();
    this.updateBestDisplay();
  }

  onDeath() {
    if (this.state !== "playing") return;
    this.state = "dead";
    this.deathTimer = 0;
    this.input.firing = false;
    this.input.ads = false;
    this.audio.defeat();
    this.setObjective("OPERATOR DOWN", "SIGNAL LOST");
    this.setSubtitle("Operator down. Blacksite 07 is dark.", 3);
    this.toast("OPERATOR KIA", "SIGNAL LOST");
    if (document.pointerLockElement) document.exitPointerLock();
    document.body.classList.remove("playing");
  }

  onEnemyKilled(enemy, headshot) {
    this.stats.kills++;
    this.stats.headshots += headshot ? 1 : 0;
    this.stats.streak++;
    this.stats.bestStreak = Math.max(this.stats.bestStreak, this.stats.streak);
    if (this.time - this.lastKillTime < 4) this.combo = Math.min(5, this.combo + 1);
    else this.combo = 1;
    this.lastKillTime = this.time;
    this.comboTimer = 4;
    const base = enemy.def.score * (headshot ? 1.5 : 1);
    this.score += Math.round(base * this.combo);
    this.wave.killed++;
    this.addKillFeed(enemy.type, headshot);
    this.showHitmarker(true, headshot);
    if (Math.random() < 0.33) {
      const type = Math.random() < 0.55 ? "ammo" : Math.random() < 0.45 ? "health" : "armor";
      this.spawnPickup(type, new THREE.Vector3(enemy.position.x + (Math.random() - 0.5) * 0.8, 0, enemy.position.z + (Math.random() - 0.5) * 0.8));
    }
    if (this.wave.killed === Math.ceil(this.wave.total * 0.5) && this.wave.active) {
      this.setSubtitle("Half their element is down. Keep pressure.", 2.4);
    }
  }

  startWave(n) {
    const table = WAVE_TABLE[n - 1];
    const queue = [];
    for (let i = 0; i < table.grunt; i++) queue.push("grunt");
    for (let i = 0; i < table.rusher; i++) queue.push("rusher");
    for (let i = 0; i < table.heavy; i++) queue.push("heavy");
    for (let i = queue.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [queue[i], queue[j]] = [queue[j], queue[i]];
    }
    this.wave.number = n;
    this.wave.total = queue.length;
    this.wave.killed = 0;
    this.wave.queue = queue;
    this.wave.spawnTimer = 0.9;
    this.wave.active = true;
    this.wave.intermission = 0;
    this.wave.victoryPending = false;
    this.enemies.difficulty = 1 + (n - 1) * 0.16;
    this.weapon.resupply();
    this.grenades = Math.min(MAX_GRENADES, this.grenades + 1);
    this.player.heal(28);
    this.player.addArmor(18);
    this.audio.waveStart();
    this.toast(`WAVE ${String(n).padStart(2, "0")}`, n === 5 ? "FINAL ASSAULT" : "HOSTILES INBOUND");
    this.setObjective(n === 5 ? "HOLD UNTIL EXTRACTION" : "HOLD THE COMPOUND", `${this.wave.total} HOSTILES · WAVE ${String(n).padStart(2, "0")} / 05`);
    this.setSubtitle(WAVE_BRIEFS[n - 1], 4);
    this.spawnPickup(n % 2 ? "ammo" : "health", this.world.pickupSpots[(n + 2) % this.world.pickupSpots.length]);
    this.updateHud(true);
  }

  completeWave() {
    if (!this.wave.active) return;
    this.wave.active = false;
    const bonus = 500 * this.wave.number;
    this.score += bonus;
    this.audio.waveClear();
    if (this.wave.number >= 5) {
      this.wave.victoryPending = true;
      this.wave.intermission = 3.2;
      this.toast("SECTOR HELD", `EXTRACTION INBOUND · +${bonus}`);
      this.setSubtitle("All hostiles neutralized. Uplink is secure. Good work, operator.", 4);
    } else {
      this.wave.intermission = 7;
      this.toast("SECTOR SECURED", `RESUPPLYING · NEXT WAVE IN 07`);
      this.setSubtitle("Wave clear. Resupply and reposition. They will hit harder next time.", 4);
      this.spawnPickup("ammo", this.world.pickupSpots[0]);
      this.spawnPickup("health", this.world.pickupSpots[1]);
      this.spawnPickup("armor", this.world.pickupSpots[2]);
      this.grenades = Math.min(MAX_GRENADES, this.grenades + 1);
    }
  }

  updateWaves(dt) {
    if (this.state !== "playing") return;
    if (this.wave.victoryPending) {
      this.wave.intermission -= dt;
      if (this.wave.intermission <= 0) this.endGame(true);
      return;
    }
    if (!this.wave.active) {
      if (this.wave.number >= 5) return;
      this.wave.intermission -= dt;
      if (this.wave.intermission <= 0) this.startWave(this.wave.number + 1);
      else if (this.wave.number > 0) {
        const secs = Math.max(1, Math.ceil(this.wave.intermission));
        $("objective-sub").textContent = `NEXT WAVE IN ${String(secs).padStart(2, "0")}`;
      }
      return;
    }
    this.wave.spawnTimer -= dt;
    const maxAlive = 6 + this.wave.number * 2;
    if (this.wave.queue.length > 0 && this.enemies.aliveCount < maxAlive && this.wave.spawnTimer <= 0) {
      const type = this.wave.queue.pop();
      const point = this.pickSpawnPoint();
      const e = this.enemies.spawn(type, point);
      e.spawnTimer = 0.65;
      this.wave.spawnTimer = Math.max(0.4, 1.35 - this.wave.number * 0.09) * (0.65 + Math.random() * 0.7);
    }
    if (this.wave.queue.length === 0 && this.enemies.aliveCount === 0) this.completeWave();
  }

  pickSpawnPoint() {
    const valid = this.world.spawnPoints.filter((p) => p.distanceTo(this.player.position) > 15);
    const pool = valid.length ? valid : this.world.spawnPoints;
    return pool[Math.floor(Math.random() * pool.length)].clone();
  }

  endGame(won) {
    if (this.state === "won" || this.resultShown) return;
    this.state = won ? "won" : "dead";
    this.resultShown = true;
    this.audio.victory?.();
    if (!won) this.audio.defeat();
    const best = Math.max(Number(localStorage.getItem("blacksite.best") || 0), Math.floor(this.score));
    try { localStorage.setItem("blacksite.best", String(best)); } catch { /* noop */ }
    this.updateBestDisplay();
    if (document.pointerLockElement) document.exitPointerLock();
    document.body.classList.remove("playing");
    $("hud").classList.add("hidden");
    $("mobile-controls").classList.add("hidden");
    const screen = $("gameover");
    screen.classList.remove("hidden");
    screen.classList.toggle("won", won);
    $("result-eyebrow").textContent = won ? "OPERATION COMPLETE" : "OPERATOR KIA";
    $("result-title").innerHTML = won ? "SECTOR<br /><em>HELD</em>" : "MISSION<br /><em>FAILED</em>";
    $("result-copy").textContent = won
      ? "The relay is secure and extraction is inbound. Blacksite 07 holds the line."
      : "The relay fell silent. The badlands keep what they take.";
    $("result-waves").textContent = `${won ? 5 : Math.max(0, this.wave.number - (this.wave.active ? 1 : 0))} / 5`;
    $("result-kills").textContent = String(this.stats.kills);
    $("result-accuracy").textContent = `${this.weapon.accuracy}%`;
    $("result-score").textContent = String(Math.floor(this.score)).padStart(6, "0");
    $("result-time").textContent = this.formatTime(this.runTime);
    $("result-streak").textContent = String(this.stats.bestStreak);
    $("result-rank").textContent = this.rankFor(this.score);
  }

  rankFor(score) {
    if (score >= 12000) return "BLACKSITE GHOST";
    if (score >= 8000) return "CAPTAIN";
    if (score >= 5000) return "LIEUTENANT";
    if (score >= 3000) return "SERGEANT";
    if (score >= 1500) return "CORPORAL";
    return "RECRUIT";
  }

  formatTime(t) {
    const m = Math.floor(t / 60);
    const s = Math.floor(t % 60);
    return `${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
  }

  updateBestDisplay() {
    let best = 0;
    try { best = Number(localStorage.getItem("blacksite.best") || 0); } catch { /* noop */ }
    $("best-score").textContent = `BEST ${String(Math.floor(best)).padStart(6, "0")}`;
  }

  showHitmarker(kill, headshot) {
    const el = $("hitmarker");
    el.classList.remove("pop", "kill");
    if (kill) el.classList.add("kill");
    if (headshot) el.classList.add("kill");
    void el.offsetWidth;
    el.classList.add("pop");
    this.damageDirTimer = Math.max(this.damageDirTimer, 0.05);
  }

  showDamageDirection(from) {
    const el = $("hit-direction");
    if (!from) {
      el.style.opacity = "1";
      this.damageDirTimer = 0.6;
      return;
    }
    const dx = from.x - this.player.position.x;
    const dz = from.z - this.player.position.z;
    const angle = Math.atan2(dx, -dz) + this.player.yaw;
    el.style.transform = `rotate(${angle}rad)`;
    el.style.opacity = "1";
    this.damageDirTimer = 0.75;
  }

  addKillFeed(type, headshot) {
    const feed = $("killfeed");
    const item = document.createElement("div");
    item.className = "feed-item";
    item.innerHTML = `<b>YOU</b> ${headshot ? '<span class="head">HEADSHOT</span>' : '<span class="hs">CQC</span>'} <span>${type.toUpperCase()}</span>`;
    feed.prepend(item);
    while (feed.children.length > 5) feed.lastChild?.remove();
    setTimeout(() => item.remove(), 3700);
  }

  toast(main, sub = "") {
    const el = $("toast");
    el.innerHTML = `${main}${sub ? `<small>${sub}</small>` : ""}`;
    el.classList.add("show");
    clearTimeout(this.toastTimer);
    this.toastTimer = setTimeout(() => el.classList.remove("show"), 2400);
  }

  setSubtitle(text, duration = 3) {
    const el = $("subtitle");
    el.textContent = text;
    el.classList.add("show");
    clearTimeout(this.subtitleTimer);
    this.subtitleTimer = setTimeout(() => el.classList.remove("show"), duration * 1000);
  }

  setObjective(main, sub) {
    $("objective-main").textContent = main;
    $("objective-sub").textContent = sub;
  }

  buildCompass() {
    const strip = $("compass-strip");
    strip.innerHTML = "";
    const cards = { 0: "N", 45: "NE", 90: "E", 135: "SE", 180: "S", 225: "SW", 270: "W", 315: "NW" };
    for (let i = 0; i < 72; i++) {
      const deg = ((i * 15) % 360 + 360) % 360;
      const span = document.createElement("span");
      if (cards[deg] !== undefined) {
        span.textContent = cards[deg];
        span.className = "card";
      } else if (deg % 30 === 0) {
        span.textContent = String(deg).padStart(3, "0");
      } else {
        span.textContent = "·";
        span.className = "tick";
      }
      strip.appendChild(span);
    }
    this.compassOffset = 0;
  }

  buildAmmoPips() {
    const pips = $("ammo-pips");
    const def = this.weapon.def;
    if (pips.childElementCount === def.magSize) return;
    pips.innerHTML = "";
    for (let i = 0; i < def.magSize; i++) pips.appendChild(document.createElement("i"));
  }

  updateHud(force = false) {
    const p = this.player;
    const w = this.weapon;
    const mag = w.ammoState.mag;
    const reserve = w.ammoState.reserve;
    $("health-value").textContent = String(Math.ceil(p.health));
    $("health-fill").style.width = `${Math.max(0, p.healthRatio * 100)}%`;
    $("health-fill").classList.toggle("low", p.healthRatio < 0.32);
    $("armor-fill").style.width = `${Math.max(0, (p.armor / p.maxArmor) * 100)}%`;
    $("ammo-mag").textContent = String(mag).padStart(2, "0");
    $("ammo-mag").classList.toggle("low", mag <= Math.max(3, w.def.magSize * 0.14));
    $("ammo-reserve").textContent = String(reserve).padStart(3, "0");
    $("weapon-name").textContent = w.def.name;
    $("weapon-mode").textContent = `${w.def.mode} · ${w.def.caliber}`;
    $("reload-prompt").classList.toggle("hidden", !(mag === 0 || w.reloading));
    $("score-value").textContent = String(Math.floor(this.score)).padStart(6, "0");
    $("combo-value").textContent = `x${this.combo}`;
    $("combo-value").classList.toggle("hidden", this.combo <= 1);
    $("grenade-count").textContent = String(this.grenades);
    $("enemies-left").textContent = String(Math.max(0, this.wave.total - this.wave.killed));
    $("wave-number").textContent = String(Math.max(1, this.wave.number));
    $("wave-progress").style.width = `${this.wave.total ? (this.wave.killed / this.wave.total) * 100 : 0}%`;
    $("pause-score").textContent = String(Math.floor(this.score)).padStart(6, "0");

    if (this.weapon.def.magSize !== $("ammo-pips").childElementCount) this.buildAmmoPips();
    const pips = $("ammo-pips").children;
    for (let i = 0; i < pips.length; i++) pips[i].classList.toggle("empty", i >= mag);

    const bearing = ((-p.yaw * 180) / Math.PI % 360 + 360) % 360;
    const idx = bearing / 15;
    const offset = 230 - idx * 23 - 11;
    $("compass-strip").style.transform = `translateX(${offset}px)`;
    $("compass-deg").textContent = String(Math.round(bearing)).padStart(3, "0");

    const spread = 4 + w.getSpread() * 720 + (p.isMoving ? 3 : 0);
    $("crosshair").style.setProperty("--spread", `${spread.toFixed(1)}px`);

    const danger = Math.min(1, p.damageFlash * 0.9 + (p.health < 35 ? 0.25 : 0));
    $("damage-vignette").style.opacity = String(danger);
  }

  drawRadar() {
    const canvas = $("radar");
    if (!canvas || canvas.offsetParent === null) return;
    const ctx = canvas.getContext("2d");
    const size = 240;
    const scale = 2.55;
    ctx.clearRect(0, 0, size, size);
    ctx.save();
    ctx.beginPath();
    ctx.arc(120, 120, 116, 0, Math.PI * 2);
    ctx.clip();
    ctx.translate(120, 120);
    // range rings
    ctx.strokeStyle = "rgba(124,231,213,0.12)";
    ctx.lineWidth = 1;
    for (const r of [34, 68, 102]) {
      ctx.beginPath();
      ctx.arc(0, 0, r, 0, Math.PI * 2);
      ctx.stroke();
    }
    // colliders as faint blocks
    for (const c of this.world.colliders) {
      if (c.top < 1.6) continue;
      const x = (c.minX - this.player.position.x) * scale;
      const y = (c.minZ - this.player.position.z) * scale;
      const w = (c.maxX - c.minX) * scale;
      const h = (c.maxZ - c.minZ) * scale;
      ctx.fillStyle = "rgba(180,190,175,0.11)";
      ctx.fillRect(x, y, w, h);
    }
    // pickups
    for (const p of this.pickups) {
      ctx.fillStyle = p.type === "health" ? "#7ce7d5" : p.type === "ammo" ? "#ffb03a" : "#9bb8ff";
      ctx.fillRect((p.group.position.x - this.player.position.x) * scale - 2, (p.group.position.z - this.player.position.z) * scale - 2, 4, 4);
    }
    // enemies
    for (const e of this.enemies.enemies) {
      if (e.dead || e.spawnTimer > 0.2) continue;
      const x = (e.position.x - this.player.position.x) * scale;
      const y = (e.position.z - this.player.position.z) * scale;
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(-e.group.rotation.y);
      ctx.fillStyle = e.type === "heavy" ? "#ff8a4a" : "#ff4d3d";
      ctx.beginPath();
      ctx.moveTo(0, -5);
      ctx.lineTo(4, 4);
      ctx.lineTo(-4, 4);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
    // fov cone
    ctx.save();
    ctx.rotate(-this.player.yaw);
    const grad = ctx.createLinearGradient(0, 0, 0, -90);
    grad.addColorStop(0, "rgba(255,176,58,0.2)");
    grad.addColorStop(1, "rgba(255,176,58,0)");
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(-44, -84);
    ctx.lineTo(44, -84);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
    // player
    ctx.fillStyle = "#f3ecdc";
    ctx.beginPath();
    ctx.moveTo(0, -7);
    ctx.lineTo(6, 7);
    ctx.lineTo(0, 4);
    ctx.lineTo(-6, 7);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  spawnPickup(type, pos) {
    if (!pos) return;
    const group = new THREE.Group();
    let color = 0xffb03a;
    if (type === "health") color = 0x7ce7d5;
    if (type === "armor") color = 0x9bb8ff;
    const base = new THREE.Mesh(
      new THREE.BoxGeometry(type === "ammo" ? 0.52 : 0.44, type === "ammo" ? 0.28 : 0.24, type === "ammo" ? 0.34 : 0.3),
      new THREE.MeshStandardMaterial({ color: type === "ammo" ? 0x4b4a35 : 0x2a3434, roughness: 0.55, metalness: 0.35 }),
    );
    base.position.y = 0.17;
    base.castShadow = true;
    group.add(base);
    const glowMat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.9 });
    if (type === "health") {
      const v = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.22, 0.02), glowMat);
      v.position.set(0, 0.18, -0.16);
      group.add(v);
      const h = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.08, 0.02), glowMat);
      h.position.set(0, 0.18, -0.16);
      group.add(h);
    } else if (type === "ammo") {
      for (let i = 0; i < 3; i++) {
        const round = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.12, 0.04), glowMat);
        round.position.set(-0.08 + i * 0.08, 0.17, -0.18);
        group.add(round);
      }
    } else {
      const plate = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.16, 0.025), glowMat);
      plate.position.set(0, 0.18, -0.17);
      group.add(plate);
    }
    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(0.38, 0.012, 4, 24),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.48, blending: THREE.AdditiveBlending, depthWrite: false }),
    );
    ring.rotation.x = Math.PI / 2;
    ring.position.y = 0.04;
    group.add(ring);
    group.position.set(pos.x, 0, pos.z);
    group.rotation.y = Math.random() * Math.PI;
    this.scene.add(group);
    this.pickups.push({ group, type, ring, phase: Math.random() * 6, life: 0 });
  }

  clearPickups() {
    for (const p of this.pickups) this.scene.remove(p.group);
    this.pickups.length = 0;
  }

  updatePickups(dt) {
    for (let i = this.pickups.length - 1; i >= 0; i--) {
      const p = this.pickups[i];
      p.life += dt;
      p.group.rotation.y += dt * 1.7;
      p.group.position.y = 0.04 + Math.sin(p.life * 2.6 + p.phase) * 0.05;
      p.ring.scale.setScalar(1 + Math.sin(p.life * 3 + p.phase) * 0.12);
      const d = Math.hypot(this.player.position.x - p.group.position.x, this.player.position.z - p.group.position.z);
      if (d < 1.25) {
        if (p.type === "ammo") {
          this.weapon.addAmmo(48);
          this.audio.pickup();
          this.toast("+48 ROUNDS", "AMMO CACHE");
        } else if (p.type === "health") {
          this.player.heal(38);
          this.audio.pickup();
          this.toast("+38 VITALS", "FIELD MEDKIT");
        } else {
          this.player.addArmor(40);
          this.audio.pickup();
          this.toast("PLATE RESTORED", "ARMOR CACHE");
        }
        this.scene.remove(p.group);
        this.pickups.splice(i, 1);
      }
    }
  }

  clearGrenades() {
    for (const g of this.grenadeProjectiles) this.scene.remove(g.mesh);
    this.grenadeProjectiles.length = 0;
  }

  throwGrenade() {
    if (this.state !== "playing" || this.grenades <= 0 || this.grenadeCooldown > 0) return;
    this.grenades--;
    this.grenadeCooldown = 0.8;
    const dir = new THREE.Vector3();
    this.camera.getWorldDirection(dir);
    const pos = new THREE.Vector3();
    this.camera.getWorldPosition(pos);
    pos.addScaledVector(dir, 0.55);
    pos.y -= 0.08;
    const mesh = new THREE.Mesh(
      new THREE.SphereGeometry(0.11, 10, 8),
      new THREE.MeshStandardMaterial({ color: 0x3b4032, roughness: 0.5, metalness: 0.4 }),
    );
    mesh.position.copy(pos);
    mesh.castShadow = true;
    this.scene.add(mesh);
    const velocity = dir.clone().multiplyScalar(15.5);
    velocity.y += 4.8;
    this.grenadeProjectiles.push({ mesh, velocity, fuse: 1.75 });
    this.audio.uiClick();
    this.toast("FRAG OUT", `${this.grenades} REMAINING`);
  }

  updateGrenades(dt) {
    this.grenadeCooldown = Math.max(0, this.grenadeCooldown - dt);
    for (let i = this.grenadeProjectiles.length - 1; i >= 0; i--) {
      const g = this.grenadeProjectiles[i];
      g.fuse -= dt;
      g.velocity.y -= 22 * dt;
      const next = g.mesh.position.clone().addScaledVector(g.velocity, dt);
      if (next.y < 0.12) {
        next.y = 0.12;
        g.velocity.y *= -0.35;
        g.velocity.x *= 0.7;
        g.velocity.z *= 0.7;
      }
      if (this.world.collidesAt(next.x, next.z, 0.12)) {
        g.velocity.x *= -0.35;
        g.velocity.z *= -0.35;
        next.x = g.mesh.position.x;
        next.z = g.mesh.position.z;
      }
      g.mesh.position.copy(next);
      g.mesh.rotation.x += dt * 9;
      g.mesh.rotation.z += dt * 7;
      if (g.fuse <= 0) {
        this.explodeGrenade(g.mesh.position.clone());
        this.scene.remove(g.mesh);
        this.grenadeProjectiles.splice(i, 1);
      }
    }
  }

  explodeGrenade(point) {
    this.fx.explosion(point, 5.5);
    this.audio.explosion();
    this.enemies.applyExplosion(point, 6.2, 190);
    const d = point.distanceTo(new THREE.Vector3(this.player.position.x, 1, this.player.position.z));
    if (d < 4.6) this.player.damage(Math.round(65 * (1 - d / 4.6)), point, "explosion");
    this.shakeScreen(0.9);
    flashScreen(0.18);
  }

  shakeScreen(amount) {
    this.player.shake = Math.min(1.4, this.player.shake + amount);
  }

  updateDeadCamera(dt) {
    this.deathTimer += dt;
    const t = Math.min(1, this.deathTimer / 1.4);
    this.camera.position.y = THREE.MathUtils.damp(this.camera.position.y, this.player.position.y + 0.45, 3.5, dt);
    this.camera.rotation.z = THREE.MathUtils.damp(this.camera.rotation.z, 0.55, 2.2, dt);
    this.camera.rotation.x = THREE.MathUtils.damp(this.camera.rotation.x, 0.12, 1.6, dt);
    if (this.deathTimer > 1.35 && !this.resultShown) this.endGame(false);
  }

  updateMenu(dt) {
    this.menuTime += dt;
    const t = this.menuTime;
    const radius = 23 + Math.sin(t * 0.075) * 4;
    const angle = t * 0.045 + 0.6;
    this.camera.position.set(Math.sin(angle) * radius, 5.7 + Math.sin(t * 0.09) * 1.5, 6 + Math.cos(angle) * radius);
    const target = new THREE.Vector3(Math.sin(t * 0.12) * 2.5, 2.7, -3 + Math.cos(t * 0.1) * 2);
    this.camera.lookAt(target);
    this.camera.rotation.z = Math.sin(t * 0.1) * 0.012;
    this.camera.fov = 62;
    this.camera.updateProjectionMatrix();
    this.enemies.update(dt, this.attractPlayer, this.time);
  }

  update(dt) {
    this.time += dt;
    this.frame++;
    this.world.update(dt, this.time);
    this.fx.update(dt);

    if (this.state === "menu") {
      this.updateMenu(dt);
      return;
    }
    if (this.state === "paused") return;
    if (this.state === "dead") {
      this.updateDeadCamera(dt);
      this.enemies.update(dt, this.player, this.time);
      this.fx.update(dt * 0.6);
      return;
    }
    if (this.state === "won") {
      this.enemies.update(dt, this.player, this.time);
      return;
    }

    this.runTime += dt;
    this.grenadeCooldown = Math.max(0, this.grenadeCooldown - dt);
    this.comboTimer -= dt;
    if (this.comboTimer <= 0) this.combo = 1;

    this.player.update(dt, this.input, this.weapon);
    this.weapon.update(dt, this.player, this.input, this.world, this.enemies);
    this.player.setAds(this.weapon.ads, this.weapon.def.adsFov);
    this.enemies.update(dt, this.player, this.time);
    this.updateWaves(dt);
    this.updatePickups(dt);
    this.updateGrenades(dt);

    this.damageDirTimer -= dt;
    if (this.damageDirTimer <= 0) $("hit-direction").style.opacity = "0";

    this.hudTimer -= dt;
    if (this.hudTimer <= 0) {
      this.hudTimer = 0.08;
      this.updateHud();
    }
    this.radarTimer -= dt;
    if (this.radarTimer <= 0) {
      this.radarTimer = 0.1;
      this.drawRadar();
    }
    if (this.player.dead && this.state === "playing") this.onDeath();
  }

  render() {
    if (this.quality === "low") {
      this.renderer.render(this.scene, this.camera);
    } else {
      this.grade.material.uniforms.uTime.value = this.time;
      this.composer.render();
    }
  }

  loop() {
    requestAnimationFrame(this.loop);
    const dt = Math.min(0.05, this.clock.getDelta());
    try {
      this.update(dt);
      this.render();
    } catch (err) {
      console.error(err);
      showBootError(err);
    }
  }
}

function flashScreen(amount) {
  const el = $("flash");
  el.style.transition = "none";
  el.style.opacity = String(amount);
  requestAnimationFrame(() => {
    el.style.transition = "opacity 0.28s ease-out";
    el.style.opacity = "0";
  });
}

function showBootError(err) {
  const el = $("boot-error");
  if (!el) return;
  el.classList.remove("hidden");
  el.textContent = `BLACKSITE BOOT FAILURE\n\n${err?.stack || err?.message || String(err)}\n\nReload the page. If this persists, WebGL2 may be unavailable.`;
}

window.addEventListener("error", (e) => {
  if (e?.error) console.error(e.error);
});
window.addEventListener("unhandledrejection", (e) => console.error(e.reason));

try {
  new Game();
} catch (err) {
  console.error(err);
  showBootError(err);
}

